67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
74	     * carrying the new owner's id, customer code and registration date.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    /**
79	     * Maximum number of owners a single city may hold. A create whose city already contains this many
80	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
81	     */
82	    private static final int MAX_OWNERS_PER_CITY = 50;
83	
84	    /**
85	     * Maximum number of owners that may be registered in a single day. A create made once this many
86	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
87	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
88	     */
89	    private static final int MAX_OWNERS_PER_DAY = 100;
90	
91	    /**
92	     * The number of owners that must already carry a given day's {@code registrationDate} before a
93	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
94	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
95	     */
96	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
97	
98	    private final ClinicService clinicService;
99	
100	    private final OwnerMapper ownerMapper;
101	
102	    private final PetMapper petMapper;
103	
104	    private final VisitMapper visitMapper;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        normalizeAddress(ownerFieldsDto);
145	        rejectBlankOwnerFields(ownerFieldsDto);
146	        rejectInvalidPostcode(ownerFieldsDto);
147	        normalizeTelephone(ownerFieldsDto);
148	        normalizeEmail(ownerFieldsDto);
149	        String householdId = HouseholdNormalizer.toHouseholdId(
150	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
151	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
152	        rejectCityAtCapacity(ownerFieldsDto.getCity());
153	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
154	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
155	        long registeredThatDay = countRegisteredOn(registrationDate);
156	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setRegistrationDate(registrationDate);
160	        owner.setHouseholdId(householdId);
161	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
162	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
163	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
164	        Integer possibleDuplicateOf = findPossibleDuplicate(owner);
165	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
166	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        currentOwner.setAddress(ownerFieldsDto.getAddress());
184	        currentOwner.setCity(ownerFieldsDto.getCity());
185	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
186	        currentOwner.setLastName(ownerFieldsDto.getLastName());
187	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
188	        normalizeEmail(ownerFieldsDto);
189	        currentOwner.setEmail(ownerFieldsDto.getEmail());
190	        currentOwner.setHouseholdId(
191	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
192	        this.clinicService.saveOwner(currentOwner);
193	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
194	    }
