260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
263	        Owner owner = this.clinicService.findOwnerById(ownerId);
264	        if (owner != null) {
265	            Pet pet = owner.getPet(petId);
266	            if (pet != null) {
267	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
268	            }
269	        }
270	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	    }
272	
273	    /**
274	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
275	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
276	     * the request body already rejects null and empty values, but permits whitespace-only strings
277	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
278	     * that gap so every required field must carry a non-blank value.
279	     *
280	     * @param ownerFieldsDto the submitted owner fields
281	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
282	     */
283	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
284	        List<String> missing = new ArrayList<>();
285	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
286	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
287	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
288	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
289	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
290	        if (!missing.isEmpty()) {
291	            throw new InvalidOwnerFieldsException(missing);
292	        }
293	    }
294	
295	    /**
296	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
297	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
298	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
299	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
300	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
301	     * {@link PostcodeValidator}.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
304	     *                       {@link #rejectBlankOwnerFields} having already run)
305	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
306	     */
307	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
308	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
309	            throw new InvalidOwnerFieldsException(List.of("postcode"));
310	        }
311	    }
312	
313	    private void addIfBlank(List<String> missing, String fieldName, String value) {
314	        if (value == null || value.isBlank()) {
315	            missing.add(fieldName);
316	        }
317	    }
318	
319	    /**
320	     * Normalizes the submitted {@code address} on create to its canonical form (see
321	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
322	     * stored and returned, and the form every later address comparison (the required-field check,
323	     * household duplicate detection and the shared household id) is judged on. A null address is left
324	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
325	     * after normalization likewise reduces to the empty string and is rejected there.
326	     *
327	     * @param ownerFieldsDto the submitted owner fields
328	     */
329	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
330	        String address = ownerFieldsDto.getAddress();
331	        if (address == null) {
332	            return;
333	        }
334	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
335	    }
336	
337	    /**
338	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
339	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
340	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
341	     * {@code 400 Bad Request}.
342	     *
343	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
344	     *                       {@link #rejectBlankOwnerFields} having already run)
345	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
346	     */
347	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
348	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
349	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
350	        ownerFieldsDto.setTelephone(normalized);
351	    }
352	
353	    /**
354	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
355	     * untouched (email is optional). When present it is reduced to its canonical form (see
356	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
357	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
358	     *
359	     * @param ownerFieldsDto the submitted owner fields
360	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
361	     */
362	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
363	        String email = ownerFieldsDto.getEmail();
364	        if (email == null || email.isBlank()) {
365	            return;
366	        }
367	        String normalized = EmailNormalizer.normalize(email)
368	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
369	        ownerFieldsDto.setEmail(normalized);
370	    }
371	
372	    /**
373	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
374	     * duplicate detection is now expressed through the single derived {@code identityKey}
375	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
376	     * which replaces the previously separate telephone, email and household checks. Two owners denote
377	     * the same person when their identities collide on the telephone - the identity's distinguishing
378	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
379	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
380	     * same household with different telephones have different identities and are both allowed; an email
381	     * or a household on its own no longer makes a duplicate.
382	     *
383	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
384	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
385	     * @param householdId    the household id derived for the owner being created (see
386	     *                       {@link HouseholdNormalizer#toHouseholdId})
387	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
388	     */
389	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
390	        String identityKey = OwnerIdentity.identityKey(
391	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
392	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
393	        boolean inUse = this.clinicService.findAllOwners().stream()
394	            .map(Owner::getTelephone)
395	            .filter(Objects::nonNull)
396	            .map(TelephoneNormalizer::toComparisonKey)
397	            .anyMatch(telephoneKey::equals);
398	        if (inUse) {
399	            throw new DuplicateOwnerIdentityException(identityKey);
400	        }
401	    }
402	
403	    /**
404	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
405	     * both match the submitted values, compared case-insensitively. The count reflects only owners
406	     * already persisted at the time of the create, so the owner being created is never included.
407	     *
408	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
409	     *                  having already run)
410	     * @param lastName  the submitted last name (non-blank here)
411	     * @return the number of existing owners sharing the same first and last name
412	     */
413	    private int countNamesakes(String firstName, String lastName) {
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
416	                && lastName.equalsIgnoreCase(owner.getLastName()))
417	            .count();
418	    }
419	
420	    /**
421	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
422	     * whose stored {@code householdId} equals the value derived for the owner being created. The
423	     * count reflects only owners already persisted at the time of the create, so the owner being
424	     * created is never included; callers add one to obtain the household size after this create.
425	     *
426	     * @param householdId the household identifier derived for the owner being created (see
427	     *                    {@link HouseholdNormalizer#toHouseholdId})
428	     * @return the number of existing owners already sharing that household
429	     */
430	    private int countHouseholdMembers(String householdId) {
431	        if (householdId == null) {
432	            return 0;
433	        }
434	        return (int) this.clinicService.findAllOwners().stream()
435	            .map(Owner::getHouseholdId)
436	            .filter(householdId::equals)
437	            .count();
438	    }
439	
440	    /**
441	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
442	     * is none. The create has already cleared the hard-duplicate identity check
443	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
444	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
445	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
446	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
447	     * original record; owners with no postcode never match, since a shared postcode is required.
448	     *
449	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
450	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
451	     *         duplicate
452	     */
453	    private Integer findPossibleDuplicate(Owner owner) {
454	        String postcode = owner.getPostcode();
455	        if (postcode == null) {
456	            return null;
457	        }
458	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
459	        return this.clinicService.findAllOwners().stream()
460	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
461	            .filter(existing -> postcode.equals(existing.getPostcode()))
462	            .filter(existing -> existing.getTelephone() != null
463	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
464	            .map(Owner::getId)
465	            .filter(Objects::nonNull)
466	            .min(Integer::compareTo)
467	            .orElse(null);
468	    }
469	
470	    /**
471	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
472	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
473	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
474	     *
475	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
476	     *             run)
477	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
478	     */
479	    private void rejectCityAtCapacity(String city) {
480	        long ownersInCity = this.clinicService.findAllOwners().stream()
481	            .map(Owner::getCity)
482	            .filter(Objects::nonNull)
483	            .filter(city::equalsIgnoreCase)
484	            .count();
485	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
486	            throw new OwnerCityAtCapacityException(city);
487	        }
488	    }
489	
490	    /**
491	     * Resolves the effective registration date for a create, rolled onto a business day. The
492	     * supplied date is used when present, otherwise the server's current date; either way the result
493	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
494	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
495	     * stored {@code registrationDate}, the membership number's year segment and the daily
496	     * create-limit's per-day count - is judged on this adjusted date.
497	     *
498	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
499	     *                                 default to the server's current date
500	     * @return the effective registration date, guaranteed to fall on a business day
501	     */
502	    /**
503	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
504	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
505	     * adjustment; a future date cannot describe a registration that has already happened, so it is
506	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
507	     * server's current date) and any date on or before today are accepted.
508	     *
509	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
510	     *                                 omitted
511	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
512	     */
513	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
514	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
515	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
516	        }
517	    }
518	
519	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
520	        LocalDate registrationDate =
521	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
522	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
523	    }
524	
525	    /**
526	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
527	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
528	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
529	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
530	     * Too Many Requests}.
531	     *
532	     * @param registrationDate   the create's effective registration date, already rolled onto a
533	     *                           business day by {@link #effectiveRegistrationDate}
534	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
535	     *                           {@code registrationDate} equals {@code registrationDate}
536	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
537	     *                                              owner registrations
538	     */
539	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
540	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
541	            throw new OwnerDailyRegistrationLimitException(registrationDate);
542	        }
543	    }
544	
545	    /**
546	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
547	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
548	     * bulk-signup warning are judged on.
549	     *
550	     * @param registrationDate the create's effective registration date, already rolled onto a business
551	     *                         day by {@link #effectiveRegistrationDate}
552	     * @return the number of existing owners registered on that day
553	     */
554	    private long countRegisteredOn(LocalDate registrationDate) {
555	        return this.clinicService.findAllOwners().stream()
556	            .map(Owner::getRegistrationDate)
557	            .filter(registrationDate::equals)
558	            .count();
559	    }
560	}
