    public OwnerCityAtCapacityException(String city) {
        super("City already at owner capacity: " + city);
        this.city = city;
    }

    public String getCity() {
        return this.city;
    }

    public String getDetail() {
        return DETAIL;
    }

    public List<String> getErrorFields() {
        return List.of("city");
    }
